package com.morphlabs.morph.core.academy.deck

import com.morphlabs.morph.core.academy.Action
import com.morphlabs.morph.core.academy.Card
import com.morphlabs.morph.core.academy.Signal
import com.morphlabs.morph.core.academy.Track

internal object FounderCards {
    private val T = Track.FOUNDER
    val cards: List<Card> = listOf(
        // ---- Level 1 · Rookie (adds to the 11 starter cards) ----------------------------------------
        concept("bo-separate-money", T, 1, "Why give your business its own M-Pesa till or bank account from day one?",
            "So you can see if the business really makes money. Mixed money hides the truth: you can't tell profit from pocket money. Keep business money apart and pay yourself from it on purpose.",
            tryThis = "Decide which number or account will be business-only.", action = Action.ACCOUNTS),
        concept("bo-revenue-profit", T, 1, "Revenue vs profit: what's the difference?",
            "Revenue is all the money customers pay you. Profit is what's left after every cost: stock, transport, rent, airtime, your helper. A kibanda selling Ksh 10,000 a day can still make a loss."),

        // ---- Level 2 · Hustler ---------------------------------------------------------------------
        quiz("bo-mom-test", T, 2, "The Mom Test says good customer interview questions are about…",
            listOf("Their life and what they did in the past", "Whether they like your idea",
                "Which features they'd want one day"), 0,
            "Even your mum will lie to be nice about your idea. Ask about specifics in their life and past behaviour, and listen more than you talk.",
            source = "Fitzpatrick, The Mom Test, 2013"),
        quiz("bo-commitment", T, 2, "After a chat, a possible customer says \"Sounds great, keep me posted!\" What have you got?",
            listOf("A compliment, not a commitment", "A strong buying signal", "A guaranteed first sale"), 0,
            "Real signals cost them something: time (a second meeting), reputation (an intro to the boss) or money (a deposit). Compliments are free.",
            source = "Fitzpatrick, The Mom Test, 2013"),
        quiz("bo-workaround", T, 2, "Which shows the strongest demand for your idea?",
            listOf("People already pay for a clumsy workaround", "Friends say they'd \"definitely\" use it",
                "Nobody else is doing it yet", "A post about it went viral"), 0,
            "If people already spend money or effort to patch the problem, the pain is real. Likes and promises cost nothing."),
        concept("bo-presell", T, 2, "How can you test demand before making anything?",
            "Pre-sell. Post \"taking orders for Friday\" on WhatsApp status and ask for a small M-Pesa deposit, or put up a simple page. If nobody pays when it's real, you've saved months.",
            tryThis = "Try to get 3 paid pre-orders before you build anything."),
        concept("bo-concierge", T, 2, "What is a \"concierge MVP\"?",
            "Serving your first customers by hand before automating. For example, plan each client's meals yourself on WhatsApp before writing an app. You learn what people truly want. Paul Graham calls it doing things that don't scale.",
            source = "Paul Graham, 2013"),
        quiz("bo-cash-vs-profit-num", T, 2, "In March you sell Ksh 50,000 of goods to a shop on 30-day credit and pay your supplier Ksh 35,000 cash. In March you have…",
            listOf("Ksh 15,000 profit, but Ksh 35,000 less cash", "Ksh 15,000 more cash", "No profit until the shop pays"), 0,
            "Profit counts the sale when it's made; cash only moves when paid. On paper you earned 15,000, but your till is 35,000 lighter until April.",
            signals = setOf(Signal.MONEY_IN_RECENT)),
        concept("bo-pay-yourself", T, 2, "What's the healthiest way for a small business owner to pay themselves?",
            "A fixed monthly amount moved from the business account. A fixed \"salary\" keeps your costs honest. If the business can't afford it yet, it isn't truly profitable: you're quietly subsidising it."),
        concept("bo-bookkeeping", T, 2, "What's the simplest bookkeeping that actually works?",
            "Record every shilling in and out daily: date, amount, what for, and how (cash, M-Pesa, bank). Keep receipts. Month end: total in − total out. A notebook or spreadsheet is enough to start.",
            tryThis = "Download this month's M-Pesa statement and tag the business lines.", action = Action.PATTERNS),
        quiz("bo-records-years", T, 2, "How long does Kenya's tax law expect you to keep business records?",
            listOf("5 years", "1 year", "Only until you file", "10 years"), 0,
            "The Tax Procedures Act requires records to be kept for 5 years from the end of the period they relate to. Photos of receipts in a cloud folder count.",
            source = "Tax Procedures Act 2015, s.23"),
        quiz("bo-net-profit", T, 2, "Juice stand: sales Ksh 60,000; fruit and cups Ksh 24,000; rent and helper Ksh 25,000. Net profit?",
            listOf("Ksh 11,000", "Ksh 36,000", "Ksh 35,000"), 0,
            "Gross profit is 60,000 − 24,000 = 36,000. Subtract fixed costs: 36,000 − 25,000 = 11,000 net. A busy stand can still earn little."),
        quiz("bo-markup-margin", T, 2, "You buy a phone cover at Ksh 200 and add a 50% markup. Your margin is…",
            listOf("About 33%", "50%", "25%"), 0,
            "Price = 300. Markup is profit ÷ cost (100 ÷ 200 = 50%); margin is profit ÷ price (100 ÷ 300 ≈ 33%). Mixing them up is how people underprice."),
        concept("bo-fixed-variable", T, 2, "Fixed vs variable costs: what's the difference, and why care?",
            "Fixed costs stay the same whether you sell 0 or 1,000 (rent, salaries, internet). Variable costs rise with each sale (stock, packaging, delivery, M-Pesa charges). Keep fixed costs low early and you survive slow months."),
        you("bo-you-salary", T, 2, "Your own fixed costs are {fixed_month} a month. What must a business pay you before quitting a job makes sense?",
            "At least {fixed_month} after all business costs, plus something to save. Until it does, many founders build on the side and keep the salary.",
            tryThis = "Track a month of side income in its own account.", action = Action.ACCOUNTS),

        // ---- Level 3 · Pro -------------------------------------------------------------------------
        quiz("bo-cac", T, 3, "You spend Ksh 20,000 on ads and flyers in a month and win 40 new customers. Customer acquisition cost (CAC)?",
            listOf("Ksh 500", "Ksh 2,000", "Ksh 50"), 0,
            "CAC = all sales and marketing spend ÷ new customers = 20,000 ÷ 40. Include your boda fare to meetings and sales staff too, or CAC looks falsely cheap."),
        quiz("bo-contribution", T, 3, "A cake sells for Ksh 1,500. Ingredients Ksh 600, box Ksh 50, boda delivery Ksh 150. Contribution per cake?",
            listOf("Ksh 700 (about 47%)", "Ksh 900 (60%)", "Ksh 850 (about 57%)"), 0,
            "Contribution = price − all variable costs = 1,500 − 800 = 700. That 700 is what pays rent and you. Forgetting delivery is the classic mistake."),
        quiz("bo-ltv-calc", T, 3, "A salon client spends Ksh 2,000 a month at a 50% contribution margin and stays 12 months. Lifetime value (LTV)?",
            listOf("Ksh 12,000", "Ksh 24,000", "Ksh 1,000"), 0,
            "LTV uses margin, not revenue: 2,000 × 50% × 12 = 12,000. Using revenue (24,000) would make you overspend on winning clients."),
        quiz("bo-payback", T, 3, "CAC is Ksh 3,000 and each customer brings Ksh 500 contribution a month. Payback period?",
            listOf("6 months", "3 months", "12 months"), 0,
            "3,000 ÷ 500 = 6 months to earn back the cost of winning them. The longer the payback, the more cash you need to grow."),
        quiz("bo-breakeven-revenue", T, 3, "Fixed costs are Ksh 90,000 a month and your contribution margin is 30%. Break-even revenue?",
            listOf("Ksh 300,000", "Ksh 270,000", "Ksh 117,000"), 0,
            "Break-even sales = fixed costs ÷ contribution margin = 90,000 ÷ 0.30 = 300,000 a month. Below that you lose money."),
        quiz("bo-price-rise", T, 3, "Your margin is 20%. You raise prices 10% and lose 10% of customers. Profit…",
            listOf("Rises by about 35%", "Falls by 10%", "Stays the same"), 0,
            "Say price 100, cost 80, 100 sales: profit 2,000. After: price 110, 90 sales → (110 − 80) × 90 = 2,700. Thin margins make price your strongest lever."),
        quiz("bo-discount", T, 3, "Your gross margin is 30%. After a 10% discount, how much more must you sell to keep the same gross profit?",
            listOf("50% more", "10% more", "30% more"), 0,
            "Price 100, cost 70: profit 30. At 90, profit is 20 per sale, so you need 30 ÷ 20 = 1.5× the sales. Discounts are expensive."),
        concept("bo-value-pricing", T, 3, "Cost-plus vs value-based pricing: what's the difference?",
            "Cost-plus: your cost plus a markup. Value-based: price on what the result is worth to the buyer. If your system saves a hotel Ksh 200,000 a month, charging Ksh 20,000 because it took 3 days leaves money behind."),
        quiz("bo-runway-calc", T, 3, "Bank: Ksh 600,000. Revenue Ksh 80,000 a month, costs Ksh 180,000 a month. Runway?",
            listOf("6 months", "3.3 months", "7.5 months"), 0,
            "Net burn = 180,000 − 80,000 = 100,000 a month. Runway = 600,000 ÷ 100,000 = 6 months. Start fixing it (or fundraising) with 6+ months left, not 2."),
        concept("bo-default-alive", T, 3, "What does Paul Graham mean by \"default alive\"?",
            "If revenue growth and costs stay as they are, do you reach profit before the cash runs out? Yes = default alive. No = default dead, so cut costs, grow faster or raise money, early.",
            source = "Paul Graham, 2015"),
        quiz("bo-ccc", T, 3, "Stock sits 30 days, customers pay after 45 days, you pay suppliers after 20 days. Cash conversion cycle?",
            listOf("55 days", "95 days", "35 days"), 0,
            "30 + 45 − 20 = 55 days your cash is tied up for every sale. Shorten it: smaller stock, M-Pesa on delivery, longer supplier terms."),
        concept("bo-growth-cash", T, 3, "Why can fast growth sink a business that sells on credit?",
            "Each new order needs cash for stock before customers pay. Working capital grows with sales. Doubling orders can double the cash stuck in stock and unpaid invoices. Plan the cash before saying yes to a huge order."),

        // ---- Level 4 · Shark: setting up in Kenya --------------------------------------------------
        concept("bo-setup-steps", T, 4, "Rough order to set up a small Kenyan business legally?",
            "1) KRA PIN (free on iTax). 2) Register a business name or company with BRS on eCitizen. 3) County Single Business Permit (yearly) plus any sector licence. 4) Tax obligations, e.g. turnover tax, and eTIMS invoicing. 5) If you hire: PAYE, NSSF, SHIF, housing levy.",
            source = "BRS; KRA, 2026", timeSensitive = true),
        quiz("bo-business-name-fee", T, 4, "Registering a sole proprietorship (business name) with BRS on eCitizen costs about…",
            listOf("Ksh 950", "Ksh 10,650", "Ksh 25,000", "It's free"), 0,
            "A business name is the cheapest way to trade under a brand. A private limited company is about Ksh 10,650. Fees change, so trust the eCitizen invoice.",
            source = "BRS via eCitizen, 2026", timeSensitive = true),
        concept("bo-liability", T, 4, "What's the biggest difference between a sole proprietorship and a private limited company?",
            "A company normally shields your personal assets from its debts. A business name isn't a separate legal person: creditors can come for your car or shamba. A company is separate; owners risk what they put in, unless they signed personal guarantees.",
            source = "Companies Act 2015"),
        concept("bo-structure", T, 4, "Sole proprietor, partnership, LLP or limited company: how do they differ?",
            "Sole/partnership: cheap and simple, unlimited personal liability. LLP (LLP Act 2011): partners get limited liability, popular with professional firms. Private limited company: limited liability, can issue shares to co-founders and investors, more filings (annual returns).",
            source = "Companies Act 2015; LLP Act 2011"),
        quiz("bo-one-director", T, 4, "Can a Kenyan private limited company have just one director and one shareholder?",
            listOf("Yes, the Companies Act 2015 allows it", "No, it needs at least two directors", "Only if it's foreign-owned"), 0,
            "Since 2015 a private company can have a single member and a single director. Small private companies with low paid-up capital don't need a company secretary.",
            source = "Companies Act 2015"),
        quiz("bo-tot", T, 4, "Turnover tax (TOT) covers resident businesses with yearly sales of…",
            listOf("Over Ksh 1M up to Ksh 25M", "Up to Ksh 5M", "Over Ksh 50M", "Any amount"), 0,
            "TOT is 1.5% of gross sales, filed and paid monthly by the 20th of the next month. Rental income and professional fees are excluded. Check KRA for changes.",
            source = "KRA, 2026", timeSensitive = true),
        quiz("bo-tot-calc", T, 4, "A shop on turnover tax sells Ksh 300,000 in March. TOT due by 20 April?",
            listOf("Ksh 4,500", "Ksh 9,000", "Ksh 48,000"), 0,
            "1.5% × 300,000 = 4,500. TOT is on sales, not profit, so you pay it even in a loss-making month. Budget for it like rent.",
            source = "KRA, 2026", timeSensitive = true),
        quiz("bo-vat-threshold", T, 4, "You must register for VAT once taxable sales exceed (or will exceed), in 12 months…",
            listOf("Ksh 5 million", "Ksh 1 million", "Ksh 25 million", "Ksh 50 million"), 0,
            "Standard VAT is 16%. You may register voluntarily below the threshold, useful if your buyers are VAT-registered and want to claim input VAT. Raising or scrapping the threshold has been debated.",
            source = "VAT Act 2013; KRA, 2026", timeSensitive = true),
        quiz("bo-etims", T, 4, "Why do business customers care whether you issue an eTIMS invoice?",
            listOf("Without one, KRA can disallow the expense in their tax", "It gives them a discount",
                "It only matters for VAT-registered sellers"), 0,
            "Since the Finance Act 2023, expenses generally must be backed by eTIMS/TIMS invoices to be tax-deductible. Non-VAT businesses can issue them too, on KRA's free eTIMS tools.",
            source = "Finance Act 2023; KRA", timeSensitive = true),
        concept("bo-bank-loan", T, 4, "Which funding usually needs collateral or a trading track record?",
            "A bank loan. Banks lend against security and statements. That's why 6–12 months of clean business statements (bank and M-Pesa) open doors. Bootstrap first, borrow once cash flow is proven."),
        concept("bo-chama-sacco", T, 4, "How can chamas and SACCOs fund a small business?",
            "A chama merry-go-round gives a lump sum when your turn comes, usually interest-free. SACCOs lend against your savings deposits, often as a multiple of them, and often cheaper than digital lenders. Both need a record of steady contributions first."),
        quiz("bo-hustler-fund", T, 4, "Kenya's Hustler Fund personal loans charge interest of about…",
            listOf("8% a year, worked out daily", "8% a month", "0%: it's a grant"), 0,
            "Short 14-day loans at about 8% p.a. (higher if late), with limits growing as you repay. Useful for stock top-ups, not for building a business on.",
            source = "Financial Inclusion Fund, 2026", timeSensitive = true),
        quiz("bo-crowdfunding", T, 4, "Under CMA's 2022 rules, a business can raise up to how much a year on a licensed crowdfunding platform?",
            listOf("Ksh 100 million", "Ksh 1 million", "Ksh 1 billion"), 0,
            "The Capital Markets (Investment-Based Crowdfunding) Regulations 2022 cap issuers at Ksh 100M per 12 months and limit how much each retail investor can put in.",
            source = "CMA Crowdfunding Regulations, 2022", timeSensitive = true),
        concept("bo-funding-ladder", T, 4, "What's the usual funding ladder for a new business?",
            "Own savings and customer pre-payments → family, friends and chama → SACCO or bank loans once cash flow is steady → grants and competitions (non-dilutive) → angels → VC, only for fast-scaling businesses. Each step up costs control or interest."),

        // ---- Level 5 · Legend ----------------------------------------------------------------------
        quiz("bo-knbs-closures", T, 5, "Kenya's 2016 MSME survey: of businesses that closed, how many died in their first year?",
            listOf("About 46%", "About 10%", "About 80%"), 0,
            "About 2.2 million MSMEs closed in the 5 years to 2016. The top reason given, by about 30%, was a shortage of operating funds.",
            source = "KNBS MSME Survey, 2016"),
        quiz("bo-cbinsights", T, 5, "In CB Insights' 2021 study of startup post-mortems, the #1 reason given for failure was…",
            listOf("Ran out of cash or couldn't raise (38%)", "Got outcompeted (20%)", "Flawed business model (19%)"), 0,
            "\"No market need\" came second at 35%. Running out of cash is often the symptom; building something nobody needs is the disease.",
            source = "CB Insights, 2021"),
        quiz("bo-bls-survival", T, 5, "US data: of business establishments born in 2013, how many were still operating in 2023?",
            listOf("About 35%", "About 10%", "About 70%"), 0,
            "Roughly 1 in 3 survive a decade, even in a rich economy. Survival is the first win; keeping costs low buys time to learn.",
            source = "US BLS, 2024"),
        concept("bo-andreessen", T, 5, "What did Marc Andreessen argue in \"The Only Thing That Matters\" (2007)?",
            "Market matters most. A great market pulls the product out of a startup; a bad market beats even a great team. Product-market fit means being in a good market with a product that satisfies it, and before you have it, nothing else matters.",
            source = "Andreessen, 2007"),
        quiz("bo-sean-ellis", T, 5, "Sean Ellis's product-market fit test asks users how they'd feel without your product. The benchmark is…",
            listOf("40%+ say \"very disappointed\"", "10%+ say \"somewhat disappointed\"", "80% would recommend it"), 0,
            "Below 40%, companies usually struggled to grow. Superhuman reportedly went from 22% to 58% by focusing on the users who loved it most.",
            source = "Sean Ellis; Rahul Vohra, 2018"),
        quiz("bo-mpesa-study", T, 5, "Suri & Jack (Science, 2016) estimated M-Pesa lifted about how many Kenyan households out of extreme poverty?",
            listOf("194,000 (about 2%)", "2 million (about 20%)", "20,000 (about 0.2%)"), 0,
            "Effects were biggest for women-headed households, partly by helping women move from farming into business. Some researchers dispute the size of the effect.",
            source = "Suri & Jack, Science, 2016"),
        concept("bo-copia", T, 5, "What can founders learn from Copia's 2024 collapse?",
            "Copia, a Kenyan rural e-commerce firm, raised over US\$100M, expanded to Uganda, cut 350 jobs in 2023, then entered administration in May 2024 when new funding failed. Low-margin, logistics-heavy models must prove profitable unit economics before expanding.",
            source = "TechCabal, 2024"),
        concept("bo-sendy", T, 5, "Why was Sendy, a Kenyan delivery startup, placed under administration in 2023?",
            "It defaulted on debt during a funding drought. It had shut a product line and cut staff in 2022, and its burn reportedly peaked near US\$1M a month. Investor money dried up before profits arrived.",
            source = "Business Daily; TechCabal, 2023"),
        concept("bo-twiga", T, 5, "Twiga Foods: what happened, and what's the lesson?",
            "Founded 2014 to link farmers to vendors, Twiga raised over US\$100M, then cut staff repeatedly from 2022; its founder-CEO left in 2024 and in 2025 it restructured into a holding company with an asset-light model. Owning trucks and stock on thin margins burns cash fast.",
            source = "TechCabal, 2024–2025"),
        concept("bo-wasoko", T, 5, "Who did Kenya's Wasoko, a B2B shop-supply startup, agree to merge with in late 2023?",
            "MaxAB of Egypt. Then in 2024 it left Zanzibar and paused Uganda and Zambia to chase profitability. After the 2021 boom, many startups merged or shrank to survive.",
            source = "TechCabal, 2024"),
        quiz("bo-wasserman", T, 5, "Noam Wasserman studied 212 startups. By year three, how many founders were no longer CEO?",
            listOf("About half", "About 5%", "About 90%"), 0,
            "Founders face a \"rich vs king\" trade-off: giving up control often builds a more valuable company, but founders who keep control stay CEO longer.",
            source = "Wasserman, HBR, 2008"),
        quiz("bo-hire-cost", T, 5, "You hire someone at Ksh 30,000 gross. What must you pay as employer, on top of salary?",
            listOf("NSSF 6% and housing levy 1.5%", "Nothing extra", "Their PAYE out of your own pocket"), 0,
            "About Ksh 2,250 more. You also deduct their own NSSF, SHIF (2.75%), housing levy and PAYE and remit them monthly. Budget about 7.5% above gross pay.",
            source = "NSSF Act 2013; Affordable Housing Act 2024; KRA, 2026", timeSensitive = true),
        concept("bo-contracts", T, 5, "What must be in writing before your first hire?",
            "Kenya's Employment Act requires a written contract for jobs over 3 months. Probation is max 6 months, extendable once (by up to 6) only with the employee's written agreement before it ends. Also put co-founder roles and shares in writing.",
            source = "Employment Act 2007, s.9 & s.42"),
    )
}
